// GENERERAD FIL – ändra inte för hand.
// Källa: generator/effekter/rum.genexpr (BLONDA RUM.amxd)
// Översatt med generator/genexpr2cpp.py från samma GenExpr som Max for Live-pluggen kör.
#pragma once
#include "blonda/gen_runtime.h"
#include <cstring>

namespace blonda::rum {

struct RumDsp {
    static constexpr int kNumOutputs = 4;
    static constexpr int kNumInputs = 2;
    static constexpr int kNumGenParams = 12;
    double samplerate = 48000.0;
    gen::Noise rng;

    // Param (sätts utifrån)
    double size = 0.55;
    double decay = 0.5;
    double damp = 0.45;
    double predel = 0.15;
    double lowc = 0.25;
    double modd = 0.35;
    double width = 1.0;
    double wet = 0.3;
    double duck = 0.0;
    double outv = 0.75;
    double shape = 0.0;
    double highc = 1.0;

    // History (tillstånd mellan sampel)
    double m_pi0 = 0.0;
    double m_pk = 0.0;
    double m_env = 0.0;
    double m_lph = 0.0;
    double m_lcs = 0.0;
    double m_lcs2 = 0.0;
    double m_hrLs = 0.0;
    double m_hrRs = 0.0;
    double m_hr2Ls = 0.0;
    double m_hr2Rs = 0.0;
    double m_z0 = 0.0;
    double m_z1 = 0.0;
    double m_z2 = 0.0;
    double m_z3 = 0.0;
    double m_z4 = 0.0;
    double m_z5 = 0.0;
    double m_z6 = 0.0;
    double m_z7 = 0.0;
    double m_wi0 = 0.0;
    double m_wi1 = 0.0;
    double m_wi2 = 0.0;
    double m_wi3 = 0.0;
    double m_wi4 = 0.0;
    double m_wi5 = 0.0;
    double m_wi6 = 0.0;
    double m_wi7 = 0.0;
    double m_api0 = 0.0;
    double m_api1 = 0.0;
    double m_api2 = 0.0;
    double m_api3 = 0.0;
    double m_sS = 0.55;

    // Data (minnesbuffertar)
    gen::Data pd{40000, 1};
    gen::Data dl0{12000, 1};
    gen::Data dl1{12000, 1};
    gen::Data dl2{12000, 1};
    gen::Data dl3{12000, 1};
    gen::Data dl4{12000, 1};
    gen::Data dl5{12000, 1};
    gen::Data dl6{12000, 1};
    gen::Data dl7{12000, 1};
    gen::Data ap0{2000, 1};
    gen::Data ap1{2000, 1};
    gen::Data ap2{2000, 1};
    gen::Data ap3{2000, 1};

    // nollställ allt tillstånd (som när gen~ laddas)
    void reset() {
        m_pi0 = 0.0;
        m_pk = 0.0;
        m_env = 0.0;
        m_lph = 0.0;
        m_lcs = 0.0;
        m_lcs2 = 0.0;
        m_hrLs = 0.0;
        m_hrRs = 0.0;
        m_hr2Ls = 0.0;
        m_hr2Rs = 0.0;
        m_z0 = 0.0;
        m_z1 = 0.0;
        m_z2 = 0.0;
        m_z3 = 0.0;
        m_z4 = 0.0;
        m_z5 = 0.0;
        m_z6 = 0.0;
        m_z7 = 0.0;
        m_wi0 = 0.0;
        m_wi1 = 0.0;
        m_wi2 = 0.0;
        m_wi3 = 0.0;
        m_wi4 = 0.0;
        m_wi5 = 0.0;
        m_wi6 = 0.0;
        m_wi7 = 0.0;
        m_api0 = 0.0;
        m_api1 = 0.0;
        m_api2 = 0.0;
        m_api3 = 0.0;
        m_sS = 0.55;
        pd.clear();
        dl0.clear();
        dl1.clear();
        dl2.clear();
        dl3.clear();
        dl4.clear();
        dl5.clear();
        dl6.clear();
        dl7.clear();
        ap0.clear();
        ap1.clear();
        ap2.clear();
        ap3.clear();
        rng = gen::Noise();
    }

    // pekare till en Param via namn (nullptr om den inte finns)
    double* param(const char* name) {
        if (std::strcmp(name, "size") == 0) return &size;
        if (std::strcmp(name, "decay") == 0) return &decay;
        if (std::strcmp(name, "damp") == 0) return &damp;
        if (std::strcmp(name, "predel") == 0) return &predel;
        if (std::strcmp(name, "lowc") == 0) return &lowc;
        if (std::strcmp(name, "modd") == 0) return &modd;
        if (std::strcmp(name, "width") == 0) return &width;
        if (std::strcmp(name, "wet") == 0) return &wet;
        if (std::strcmp(name, "duck") == 0) return &duck;
        if (std::strcmp(name, "outv") == 0) return &outv;
        if (std::strcmp(name, "shape") == 0) return &shape;
        if (std::strcmp(name, "highc") == 0) return &highc;
        return nullptr;
    }

    // ett sampel; in har kNumInputs värden, out får kNumOutputs värden
    inline void perform(const double* in, double* out) {
        double m_apd0 = 0.0, m_apd1 = 0.0, m_apd2 = 0.0, m_apd3 = 0.0, m_apn0 = 0.0, m_apn1 = 0.0, m_apn2 = 0.0, m_apn3 = 0.0;
        double m_apr0 = 0.0, m_apr1 = 0.0, m_apr2 = 0.0, m_apr3 = 0.0, m_apv0 = 0.0, m_apv1 = 0.0, m_apv2 = 0.0, m_apv3 = 0.0;
        double m_dk = 0.0, m_dkk = 0.0, m_dmpf = 0.0, m_dryG = 0.0, m_g0 = 0.0, m_g1 = 0.0, m_g2 = 0.0, m_g3 = 0.0;
        double m_g4 = 0.0, m_g5 = 0.0, m_g6 = 0.0, m_g7 = 0.0, m_hr2Lk = 0.0, m_hr2Lo = 0.0, m_hr2Rk = 0.0, m_hr2Ro = 0.0;
        double m_hrLk = 0.0, m_hrLo = 0.0, m_hrRk = 0.0, m_hrRo = 0.0, m_hrf = 0.0, m_hs = 0.0, m_ia = 0.0, m_lck = 0.0;
        double m_lco = 0.0, m_ln0 = 0.0, m_ln1 = 0.0, m_ln2 = 0.0, m_ln3 = 0.0, m_ln4 = 0.0, m_ln5 = 0.0, m_ln6 = 0.0;
        double m_ln7 = 0.0, m_mid = 0.0, m_oL = 0.0, m_oR = 0.0, m_pdN = 0.0, m_pds = 0.0, m_pr = 0.0, m_rfr0 = 0.0;
        double m_rfr1 = 0.0, m_rfr2 = 0.0, m_rfr3 = 0.0, m_rfr4 = 0.0, m_rfr5 = 0.0, m_rfr6 = 0.0, m_rfr7 = 0.0, m_ri0 = 0.0;
        double m_ri1 = 0.0, m_ri2 = 0.0, m_ri3 = 0.0, m_ri4 = 0.0, m_ri5 = 0.0, m_ri6 = 0.0, m_ri7 = 0.0, m_rp0 = 0.0;
        double m_rp1 = 0.0, m_rp2 = 0.0, m_rp3 = 0.0, m_rp4 = 0.0, m_rp5 = 0.0, m_rp6 = 0.0, m_rp7 = 0.0, m_rt = 0.0;
        double m_sc = 0.0, m_side = 0.0, m_sr = 0.0, m_wetG = 0.0, m_wetL = 0.0, m_wetR = 0.0, m_wl = 0.0, m_wr = 0.0;
        double m_x = 0.0, m_y0 = 0.0, m_y1 = 0.0, m_y2 = 0.0, m_y3 = 0.0, m_y4 = 0.0, m_y5 = 0.0, m_y6 = 0.0;
        double m_y7 = 0.0;
        m_sr = samplerate;
        m_sS = m_sS + (size - m_sS) * 0.0005;
        m_sc = (0.35 + m_sS * 1.65) * (shape > 0.5 ? 0.75 : 1.0) * m_sr / 1000.0;
        m_rt = 0.25 * std::pow(40.0, decay) * (shape > 0.5 ? 0.8 : 1.0);
        m_dmpf = 1500.0 + (1.0 - damp) * (1.0 - damp) * 16000.0;
        m_dk = 1.0 - std::exp(-gen::kTwoPi * m_dmpf / m_sr);
        m_pdN = 40000.0;
        pd.poke( (in[0] + in[1]) * 0.5, m_pi0, 0.0);
        m_pds = gen::clamp(predel * predel * 0.25 * m_sr, 1.0, m_pdN - 2.0);
        m_pr = gen::wrap(m_pi0 - m_pds, 0.0, m_pdN);
        m_x = pd.peek( m_pr, 0.0);
        m_pi0 = gen::wrap(m_pi0 + 1.0, 0.0, m_pdN);
        m_lck = 1.0 - std::exp(-gen::kTwoPi * (20.0 + lowc * lowc * 600.0) / m_sr);
        m_lcs = m_lcs + ((m_x) - m_lcs) * m_lck;
        m_lco = (m_x) - m_lcs;
        m_x = m_lco;
        m_apn0 = gen::min(std::floor(4.77 * m_sr / 1000.0 * (0.6 + m_sS * 0.6)), 1999.0);
        m_apr0 = gen::wrap(m_api0 - m_apn0, 0.0, 2000.0);
        m_apd0 = ap0.peek( m_apr0, 0.0);
        m_apv0 = m_x + m_apd0 * 0.6;
        ap0.poke( m_apv0, m_api0, 0.0);
        m_api0 = gen::wrap(m_api0 + 1.0, 0.0, 2000.0);
        m_x = m_apd0 - m_apv0 * 0.6;
        m_apn1 = gen::min(std::floor(3.59 * m_sr / 1000.0 * (0.6 + m_sS * 0.6)), 1999.0);
        m_apr1 = gen::wrap(m_api1 - m_apn1, 0.0, 2000.0);
        m_apd1 = ap1.peek( m_apr1, 0.0);
        m_apv1 = m_x + m_apd1 * 0.6;
        ap1.poke( m_apv1, m_api1, 0.0);
        m_api1 = gen::wrap(m_api1 + 1.0, 0.0, 2000.0);
        m_x = m_apd1 - m_apv1 * 0.6;
        m_apn2 = gen::min(std::floor(12.73 * m_sr / 1000.0 * (0.6 + m_sS * 0.6)), 1999.0);
        m_apr2 = gen::wrap(m_api2 - m_apn2, 0.0, 2000.0);
        m_apd2 = ap2.peek( m_apr2, 0.0);
        m_apv2 = m_x + m_apd2 * 0.6;
        ap2.poke( m_apv2, m_api2, 0.0);
        m_api2 = gen::wrap(m_api2 + 1.0, 0.0, 2000.0);
        m_x = m_apd2 - m_apv2 * 0.6;
        m_apn3 = gen::min(std::floor(9.31 * m_sr / 1000.0 * (0.6 + m_sS * 0.6)), 1999.0);
        m_apr3 = gen::wrap(m_api3 - m_apn3, 0.0, 2000.0);
        m_apd3 = ap3.peek( m_apr3, 0.0);
        m_apv3 = m_x + m_apd3 * 0.6;
        ap3.poke( m_apv3, m_api3, 0.0);
        m_api3 = gen::wrap(m_api3 + 1.0, 0.0, 2000.0);
        m_x = m_apd3 - m_apv3 * 0.6;
        m_lph = gen::wrap(m_lph + 0.37 / m_sr, 0.0, 1.0);
        m_ln0 = gen::clamp(29.7 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.00 + 0.0)) * modd * 9.0, 4.0, 11990.0);
        m_rp0 = m_wi0 - m_ln0;
        m_rp0 = m_rp0 < 0.0 ? m_rp0 + 12000.0 : m_rp0;
        m_ri0 = std::floor(m_rp0);
        m_rfr0 = m_rp0 - m_ri0;
        m_y0 = dl0.peek( m_ri0, 0.0) * (1.0 - m_rfr0) + dl0.peek( gen::wrap(m_ri0 + 1.0, 0.0, 12000.0), 0.0) * m_rfr0;
        m_g0 = std::pow(10.0, -3.0 * m_ln0 / m_sr / m_rt);
        m_z0 = m_z0 + (m_y0 * m_g0 - m_z0) * m_dk;
        m_ln1 = gen::clamp(37.1 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.13 + 0.125)) * modd * 8.4, 4.0, 11990.0);
        m_rp1 = m_wi1 - m_ln1;
        m_rp1 = m_rp1 < 0.0 ? m_rp1 + 12000.0 : m_rp1;
        m_ri1 = std::floor(m_rp1);
        m_rfr1 = m_rp1 - m_ri1;
        m_y1 = dl1.peek( m_ri1, 0.0) * (1.0 - m_rfr1) + dl1.peek( gen::wrap(m_ri1 + 1.0, 0.0, 12000.0), 0.0) * m_rfr1;
        m_g1 = std::pow(10.0, -3.0 * m_ln1 / m_sr / m_rt);
        m_z1 = m_z1 + (m_y1 * m_g1 - m_z1) * m_dk;
        m_ln2 = gen::clamp(41.1 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.26 + 0.25)) * modd * 7.8, 4.0, 11990.0);
        m_rp2 = m_wi2 - m_ln2;
        m_rp2 = m_rp2 < 0.0 ? m_rp2 + 12000.0 : m_rp2;
        m_ri2 = std::floor(m_rp2);
        m_rfr2 = m_rp2 - m_ri2;
        m_y2 = dl2.peek( m_ri2, 0.0) * (1.0 - m_rfr2) + dl2.peek( gen::wrap(m_ri2 + 1.0, 0.0, 12000.0), 0.0) * m_rfr2;
        m_g2 = std::pow(10.0, -3.0 * m_ln2 / m_sr / m_rt);
        m_z2 = m_z2 + (m_y2 * m_g2 - m_z2) * m_dk;
        m_ln3 = gen::clamp(43.7 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.39 + 0.375)) * modd * 7.2, 4.0, 11990.0);
        m_rp3 = m_wi3 - m_ln3;
        m_rp3 = m_rp3 < 0.0 ? m_rp3 + 12000.0 : m_rp3;
        m_ri3 = std::floor(m_rp3);
        m_rfr3 = m_rp3 - m_ri3;
        m_y3 = dl3.peek( m_ri3, 0.0) * (1.0 - m_rfr3) + dl3.peek( gen::wrap(m_ri3 + 1.0, 0.0, 12000.0), 0.0) * m_rfr3;
        m_g3 = std::pow(10.0, -3.0 * m_ln3 / m_sr / m_rt);
        m_z3 = m_z3 + (m_y3 * m_g3 - m_z3) * m_dk;
        m_ln4 = gen::clamp(53.9 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.52 + 0.5)) * modd * 6.6, 4.0, 11990.0);
        m_rp4 = m_wi4 - m_ln4;
        m_rp4 = m_rp4 < 0.0 ? m_rp4 + 12000.0 : m_rp4;
        m_ri4 = std::floor(m_rp4);
        m_rfr4 = m_rp4 - m_ri4;
        m_y4 = dl4.peek( m_ri4, 0.0) * (1.0 - m_rfr4) + dl4.peek( gen::wrap(m_ri4 + 1.0, 0.0, 12000.0), 0.0) * m_rfr4;
        m_g4 = std::pow(10.0, -3.0 * m_ln4 / m_sr / m_rt);
        m_z4 = m_z4 + (m_y4 * m_g4 - m_z4) * m_dk;
        m_ln5 = gen::clamp(61.3 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.65 + 0.625)) * modd * 6.0, 4.0, 11990.0);
        m_rp5 = m_wi5 - m_ln5;
        m_rp5 = m_rp5 < 0.0 ? m_rp5 + 12000.0 : m_rp5;
        m_ri5 = std::floor(m_rp5);
        m_rfr5 = m_rp5 - m_ri5;
        m_y5 = dl5.peek( m_ri5, 0.0) * (1.0 - m_rfr5) + dl5.peek( gen::wrap(m_ri5 + 1.0, 0.0, 12000.0), 0.0) * m_rfr5;
        m_g5 = std::pow(10.0, -3.0 * m_ln5 / m_sr / m_rt);
        m_z5 = m_z5 + (m_y5 * m_g5 - m_z5) * m_dk;
        m_ln6 = gen::clamp(67.9 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.78 + 0.75)) * modd * 5.4, 4.0, 11990.0);
        m_rp6 = m_wi6 - m_ln6;
        m_rp6 = m_rp6 < 0.0 ? m_rp6 + 12000.0 : m_rp6;
        m_ri6 = std::floor(m_rp6);
        m_rfr6 = m_rp6 - m_ri6;
        m_y6 = dl6.peek( m_ri6, 0.0) * (1.0 - m_rfr6) + dl6.peek( gen::wrap(m_ri6 + 1.0, 0.0, 12000.0), 0.0) * m_rfr6;
        m_g6 = std::pow(10.0, -3.0 * m_ln6 / m_sr / m_rt);
        m_z6 = m_z6 + (m_y6 * m_g6 - m_z6) * m_dk;
        m_ln7 = gen::clamp(73.1 * m_sc + std::sin(gen::kTwoPi * (m_lph * 1.91 + 0.875)) * modd * 4.8, 4.0, 11990.0);
        m_rp7 = m_wi7 - m_ln7;
        m_rp7 = m_rp7 < 0.0 ? m_rp7 + 12000.0 : m_rp7;
        m_ri7 = std::floor(m_rp7);
        m_rfr7 = m_rp7 - m_ri7;
        m_y7 = dl7.peek( m_ri7, 0.0) * (1.0 - m_rfr7) + dl7.peek( gen::wrap(m_ri7 + 1.0, 0.0, 12000.0), 0.0) * m_rfr7;
        m_g7 = std::pow(10.0, -3.0 * m_ln7 / m_sr / m_rt);
        m_z7 = m_z7 + (m_y7 * m_g7 - m_z7) * m_dk;
        m_hs = (m_z0 + m_z1 + m_z2 + m_z3 + m_z4 + m_z5 + m_z6 + m_z7) * 0.25;
        dl0.poke( m_z0 - m_hs + m_x * 0.35, m_wi0, 0.0);
        m_wi0 = gen::wrap(m_wi0 + 1.0, 0.0, 12000.0);
        dl1.poke( m_z1 - m_hs + m_x * -0.35, m_wi1, 0.0);
        m_wi1 = gen::wrap(m_wi1 + 1.0, 0.0, 12000.0);
        dl2.poke( m_z2 - m_hs + m_x * 0.35, m_wi2, 0.0);
        m_wi2 = gen::wrap(m_wi2 + 1.0, 0.0, 12000.0);
        dl3.poke( m_z3 - m_hs + m_x * -0.35, m_wi3, 0.0);
        m_wi3 = gen::wrap(m_wi3 + 1.0, 0.0, 12000.0);
        dl4.poke( m_z4 - m_hs + m_x * 0.35, m_wi4, 0.0);
        m_wi4 = gen::wrap(m_wi4 + 1.0, 0.0, 12000.0);
        dl5.poke( m_z5 - m_hs + m_x * -0.35, m_wi5, 0.0);
        m_wi5 = gen::wrap(m_wi5 + 1.0, 0.0, 12000.0);
        dl6.poke( m_z6 - m_hs + m_x * 0.35, m_wi6, 0.0);
        m_wi6 = gen::wrap(m_wi6 + 1.0, 0.0, 12000.0);
        dl7.poke( m_z7 - m_hs + m_x * -0.35, m_wi7, 0.0);
        m_wi7 = gen::wrap(m_wi7 + 1.0, 0.0, 12000.0);
        m_wl = (m_z0 - m_z2 + m_z4 - m_z6 + m_z1 * 0.5) * 0.6;
        m_wr = (m_z1 - m_z3 + m_z5 - m_z7 + m_z2 * 0.5) * 0.6;
        m_hrf = gen::min(20000.0 * std::pow(0.03, 1.0 - highc), m_sr * 0.45);
        m_hrLk = 1.0 - std::exp(-gen::kTwoPi * (m_hrf) / m_sr);
        m_hrLs = m_hrLs + ((m_wl) - m_hrLs) * m_hrLk;
        m_hrLo = m_hrLs;
        m_hrRk = 1.0 - std::exp(-gen::kTwoPi * (m_hrf) / m_sr);
        m_hrRs = m_hrRs + ((m_wr) - m_hrRs) * m_hrRk;
        m_hrRo = m_hrRs;
        m_hr2Lk = 1.0 - std::exp(-gen::kTwoPi * (m_hrf) / m_sr);
        m_hr2Ls = m_hr2Ls + ((m_hrLo) - m_hr2Ls) * m_hr2Lk;
        m_hr2Lo = m_hr2Ls;
        m_hr2Rk = 1.0 - std::exp(-gen::kTwoPi * (m_hrf) / m_sr);
        m_hr2Rs = m_hr2Rs + ((m_hrRo) - m_hr2Rs) * m_hr2Rk;
        m_hr2Ro = m_hr2Rs;
        m_wl = highc > 0.995 ? m_wl : m_hr2Lo;
        m_wr = highc > 0.995 ? m_wr : m_hr2Ro;
        m_ia = std::fabs(in[0]) + std::fabs(in[1]);
        m_env = m_ia > m_env ? m_env + (m_ia - m_env) * 0.01 : m_env * 0.99985;
        m_dkk = 1.0 / (1.0 + m_env * duck * 8.0);
        m_mid = (m_wl + m_wr) * 0.5;
        m_side = (m_wl - m_wr) * 0.5 * width;
        m_wetL = (m_mid + m_side) * m_dkk;
        m_wetR = (m_mid - m_side) * m_dkk;
        m_dryG = wet < 0.5 ? 1.0 : 2.0 - 2.0 * wet;
        m_wetG = wet < 0.5 ? 2.0 * wet : 1.0;
        m_oL = (in[0] * m_dryG + m_wetL * m_wetG) * outv * 1.33;
        m_oR = (in[1] * m_dryG + m_wetR * m_wetG) * outv * 1.33;
        m_oL = std::tanh(m_oL * 0.9) / 0.9;
        m_oR = std::tanh(m_oR * 0.9) / 0.9;
        m_pk = gen::max(std::fabs(m_wetL) + std::fabs(m_wetR), m_pk * 0.9997);
        out[0] = m_oL;
        out[1] = m_oR;
        out[2] = m_pk * 0.5;
        out[3] = m_env;
    }
};

}  // namespace blonda::rum
